    'pre_sha','','post_sha','','status','OPEN','error',struct());

pR=which('REPLANNING_SYSTEM');
assert(~isempty(pR)&&isfile(pR),'[AF7R58ZZV-R2] REPLANNING_SYSTEM unresolved.');
root=fileparts(pR);

outdir=tempname(root);
[ok,msg]=mkdir(outdir); assert(ok,'%s',msg);
report=fullfile(outdir,'AF7R58ZZV_R2_REPORT.txt');
