say(fid,' AF7R58ZZV-R2 | CONSTRUCTOR SIGNATURE CACHE-ORDER FIX');
say(fid,'====================================================================================================');
say(fid,'[ROOTCAUSE] validator used runtime signature cache before constructor captured it');
say(fid,'[FIX] constructorExactFunc2strOnce=1 | cachedBindingAfterCapture=1');
say(fid,'[FLIGHT] perCycleFunc2str=0 | hotGuardUnchanged=1');
say(fid,'[WORKER] process=0 | thread=0 | parpool=0 | parfeval=0');
say(fid,'[SAFETY] fixedH4s=1 | finiteSensingChanged=0 | certificateMathChanged=0');

