    gz=matlab.net.base64decode([B64{:}]);
    gzPath=fullfile(stage,'REPLANNING_SYSTEM.m.gz');
    ff=fopen(gzPath,'wb'); assert(ff>=0);
    fwrite(ff,uint8(gz),'uint8'); fclose(ff);
    gunzip(gzPath,stage);
    staged=fullfile(stage,'REPLANNING_SYSTEM.m');
    assert(strcmp(file_hash(staged),POST_SHA), ...
        '[AF7R58ZZV-R2] staged candidate SHA mismatch.');

    R=read_utf8(staged);

    % Exact pre-write audit.
    h=regexp(R, ...
        '(?m)^[ \t]*horizon_s[ \t]*=[ \t]*4\.0;[ \t]*(%[^\r\n]*)?$', ...
        'match');
    assert(numel(h)==1,'[AF7R58ZZV-R2] fixed H=4 s unresolved.');
    assert(~contains(R,'process_worker_'));
    assert(~contains(R,'parfeval'));
    assert(~contains(R,'parpool'));
    assert(contains(R,'AF7R58ZZV-R2 constructor-safe signature binding.'));
    assert(contains(R,'cacheReady = ...'));
    assert(contains(R,'func2str(obj.base_ref.func)'));
    assert(contains(R,'function assert_runtime_core_certificates_current_hot(obj)'));
    assert(contains(R,'AF7R58ZZV_PREPARED_COMMIT_V2'));
    assert(contains(R,'''detected_only_obstacle_contract'',true'));
    assert(contains(R,'obj.evaluate_reference_only_proposal_certificate(P);'));

    % Full patched class parse before production write.
    parseDir=fullfile(outdir,'PARSE');
    [ok,msg]=mkdir(parseDir); assert(ok,'%s',msg);
    parseName='AF7R58ZZV_R2_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(R,'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    assert(~strcmp(parseText,R),'[AF7R58ZZV-R2] class rename failed.');
    parsePath=fullfile(parseDir,[parseName '.m']);
    write_utf8(parsePath,parseText);
    addpath(parseDir,'-begin');
    cp=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZZV-R2] patched class parse failed.');
    eval(['clear ' parseName]);

    say(fid,'');
    say(fid,'[A. PREFLIGHT]');
    say(fid,' exact PRE SHA                      = 1 | %s',pre);
    say(fid,' exact staged POST SHA              = 1 | %s',POST_SHA);
    say(fid,' constructor pre-cache fallback     = exact func2str once');
    say(fid,' cached binding after capture        = 1');
    say(fid,' Flight hot per-cycle func2str       = 0');
    say(fid,' worker/thread/process offload       = 0');
    say(fid,' staged two-spike optimization kept  = 1');
    say(fid,' continuous certificate kept         = 1');
    say(fid,' full patched class parse            = 1');
    say(fid,' production writes                   = 0');

    copyfile(pR,backup,'f');
    wrote=true;
    copyfile(staged,pR,'f');

    post=file_hash(pR);
    OUT.post_sha=post;
    assert(strcmp(post,POST_SHA),'[AF7R58ZZV-R2] POST SHA mismatch.');

    OUT.production_modified=true;
    OUT.status='ZZV_CONSTRUCTOR_SIGNATURE_FIX_INSTALLED__CLEAN_RERUN_REQUIRED';

    say(fid,'');
    say(fid,'[B. INSTALL]');
    say(fid,' REPLANNING_SYSTEM post SHA = %s',post);
    say(fid,' status = %s',OUT.status);

catch ME
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});
    try
        if wrote && isfile(backup)
            copyfile(backup,pR,'f');
            OUT.rollback_performed=true;
        end
    catch
    end
    OUT.production_modified=false;
    OUT.status='INSTALL_FAILED__ROLLBACK_ATTEMPTED';
    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier = %s',ME.identifier);
    say(fid,' message    = %s',ME.message);
    if ~isempty(ME.stack), say(fid,' line       = %d',ME.stack(1).line); end
    say(fid,' rollback   = %d',OUT.rollback_performed);
end

OUT.report_path=report;
OUT.mat_path=matp;
save(matp,'OUT','-v7');
assignin('base','AF7R58ZZV_R2_OUT',OUT);
say(fid,'');
say(fid,'RETURN: %s',report);
say(fid,'RETURN: %s',matp);
say(fid,'status = %s',OUT.status);
end

function s=read_utf8(path)
fid=fopen(path,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,'*uint8');
s=native2unicode(b.','UTF-8');
end

function write_utf8(path,s)
b=unicode2native(s,'UTF-8');
fid=fopen(path,'wb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid,uint8(b),'uint8');
end

function h=file_hash(path)
md=java.security.MessageDigest.getInstance('SHA-256');
fid=fopen(path,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
while true
    b=fread(fid,1024*1024,'*uint8');
    if isempty(b), break; end
    md.update(b);
end
u=typecast(md.digest(),'uint8');
h=lower(reshape(dec2hex(u,2).',1,[]));
end

function say(fid,varargin)
fprintf(fid,[varargin{1} '\n'],varargin{2:end});
fprintf([varargin{1} '\n'],varargin{2:end});
end

function safe_rmpath(p)
try, rmpath(p); catch, end
end

function safe_fclose(fid)
try, fclose(fid); catch, end
end
